solution.code:
// money.ts
export function add(a: number, b: number): number {
  return a + b;
}
export default function formatMoney(n: number): string {
  return '$' + n.toFixed(2);
}

// Consumer:  import formatMoney, { add } from './money';
console.log(add(2, 3));
console.log(formatMoney(add(2, 3)));

