solution.code:
// logger.ts:  export default function log(msg: string) { console.log('[log]', msg); }

// consumer.ts — correct default import (no braces):
// import log from './logger';
const loggerModule = { default: (msg) => console.log('[log]', msg) };
const log = loggerModule.default; // grab the default
log('hello');

